## 2. `app.py` (Backend)

```python
import os
import uuid
import secrets
import hashlib
from flask import Flask, request, jsonify, send_file, render_template

app = Flask(__name__)
app.config['MAX_CONTENT_LENGTH'] = 100 * 1024 * 1024  # 100MB max

UPLOAD_DIR = 'uploads'
os.makedirs(UPLOAD_DIR, exist_ok=True)

# In-memory store: { file_id: { filename, password_hash, path } }
files_db = {}


def hash_password(password):
    return hashlib.sha256(password.encode()).hexdigest()


@app.route('/')
def index():
    return render_template('index.html')


@app.route('/upload', methods=['POST'])
def upload():
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    password = request.form.get('password', '')

    if not file.filename or not password:
        return jsonify({'error': 'File and password required'}), 400

    file_id = uuid.uuid4().hex
    safe_name = os.path.basename(file.filename)
    path = os.path.join(UPLOAD_DIR, file_id + '_' + safe_name)
    file.save(path)

    files_db[file_id] = {
        'filename': safe_name,
        'password_hash': hash_password(password),
        'path': path,
    }

    share_link = f"{request.host_url}download/{file_id}"
    return jsonify({'link': share_link, 'file_id': file_id})


@app.route('/api/verify/<file_id>', methods=['POST'])
def verify(file_id):
    if file_id not in files_db:
        return jsonify({'error': 'File not found'}), 404

    password = request.json.get('password', '')
    if hash_password(password) == files_db[file_id]['password_hash']:
        # Generate a one-time token for this session
        token = secrets.token_urlsafe(32)
        files_db[file_id].setdefault('tokens', set()).add(token)
        return jsonify({'token': token})
    return jsonify({'error': 'Incorrect password'}), 403


@app.route('/download/<file_id>')
def download_page(file_id):
    if file_id not in files_db:
        return "File not found", 404
    return render_template('index.html', download_id=file_id)


@app.route('/api/file/<file_id>')
def get_file(file_id):
    if file_id not in files_db:
        return jsonify({'error': 'File not found'}), 404

    token = request.args.get('token', '')
    entry = files_db[file_id]
    if token not in entry.get('tokens', set()):
        return jsonify({'error': 'Unauthorized'}), 403

    return send_file(entry['path'], as_attachment=True, download_name=entry['filename'])


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
```

