        function showMessage(text, type) {
            const m = document.getElementById('message');
            m.textContent = text;
            m.className = 'message ' + type;
            m.style.display = 'block';
        }

        async function doUpload() {
            const file = document.getElementById('fileInput').files[0];
            const password = document.getElementById('passwordInput').value;
            if (!file) return showMessage('Please select a file', 'error');
            if (!password) return showMessage('Please enter a password', 'error');

            const btn = document.getElementById('uploadBtn');
            btn.disabled = true;
            btn.textContent = 'Uploading...';

            const formData = new FormData();
            formData.append('file', file);
            formData.append('password', password);

            try {
                const res = await fetch('/upload', { method: 'POST', body: formData });
                const data = await res.json();
                if (!res.ok) throw new Error(data.error);

                showMessage('✅ File uploaded successfully!', 'success');
                const linkArea = document.getElementById('linkArea');
                linkArea.innerHTML = `
                    <div class="link-box" id="linkText">${data.link}</div>
                    <button class="copy-btn" onclick="copyLink()">Copy Link</button>
                `;
                window._shareLink = data.link;
                btn.textContent = 'Upload & Generate Link';
                btn.disabled = false;
            } catch (e) {
                showMessage('Error: ' + e.message, 'error');
                btn.textContent = 'Upload & Generate Link';
                btn.disabled = false;
            }
        }

        function copyLink() {
            navigator.clipboard.writeText(window._shareLink);
            const btn = document.querySelector('.copy-btn');
            btn.textContent = '✅ Copied!';
            setTimeout(() => btn.textContent = 'Copy Link', 2000);
        }

        async function doDownload() {
            const password = document.getElementById('passwordInput').value;
            if (!password) return showMessage('Please enter a password', 'error');

            const btn = document.getElementById('downloadBtn');
            btn.disabled = true;
            btn.textContent = 'Verifying...';

            try {
                const res = await fetch(`/api/verify/${downloadId}`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ password })
                });
                const data = await res.json();
                if (!res.ok) throw new Error(data.error);

                // Trigger download
                window.location.href = `/api/file/${downloadId}?token=${data.token}`;
                showMessage('✅ Password correct! Download starting...', 'success');
                btn.textContent = 'Unlock & Download';
                btn.disabled = false;
            } catch (e) {
                showMessage('❌ ' + e.message, 'error');
                btn.textContent = 'Unlock & Download';
                btn.disabled = false;
            }
        }

        if (isDownload) renderDownload();
        else renderUpload();
    </script>
</body>
</html>
```

## How to run it

```bash
# Create the files above, then:
pip install -r requirements.txt
python app.py
```

Then open **http://localhost:5000** in your browser.

## How it works

1. **Upload flow**: You select a file, choose a password → the server stores it and returns a share link like `http://localhost:5000/download/abc123def...`
2. **Share flow**: Send that link to your friends.
3. **Download flow**: Your friend opens the link, enters the password → server verifies the hash → issues a one-time token → browser downloads the file.

## Security notes

- ✅ Passwords are hashed with SHA-256 (never stored in plain text)
- ✅ Downloads require a valid token issued only after correct password
- ✅ Files are stored with UUID prefixes (no filename collisions)
- ✅ File paths use `os.path.basename()` to prevent path traversal
- ⚠️ **For production**, add: HTTPS (behind nginx/reverse proxy), rate limiting on password attempts, a real database, and file expiration. The in-memory `files_db` is lost on restart — swap for SQLite if you need persistence.

## Optional: Deploy online for free

- **Render.com** or **Fly.io** — deploy as-is (change `host='0.0.0.0'`, run via gunicorn)
- Use **`gunicorn app:app`** in production and add `gunicorn` to `requirements.txt`
- Note that files stored on free tiers may be ephemeral — use persistent disk or S3 for uploads

